{
  "fixedHtml": "<input autocomplete=\"bday\" id=\"ubirthday\" type=\"text\">",
  "explanation": "The `autocomplete` attribute for the birthday input was changed from the invalid token 'birthday' to the correct HTML specification token 'bday'. This allows user agents to programmatically determine the input's purpose, fulfilling WCAG 1.3.5.",
  "effort": "low"
}

{
  "fixedHtml": "<img src=\"squiggle.gif\" height=\"20\" width=\"20\" alt=\"\">",
  "explanation": "Added an empty `alt` attribute (`alt=\"\"`) to the `<img>` element. This signals to assistive technologies that the image is purely decorative and conveys no meaningful information, ensuring it is ignored by screen readers. This resolves WCAG 1.1.1 by providing appropriate text alternatives for non-text content, specifically by indicating that no alternative is needed for decorative images.",
  "effort": "low"
}

{
  "fixedHtml": "<div>\n  Tree type: <img src=\"spacer.gif\" width=\"100\" height=\"1\" alt=\"\">\n  Cedrus deodara\n</div>",
  "explanation": "The `alt` attribute was changed from `alt=\"spacer\"` to `alt=\"\"`. For images that are purely decorative or used for visual spacing and convey no information, an empty `alt` attribute signals to screen readers that the image should be ignored, preventing it from being announced and improving the user experience for assistive technology users.",
  "effort": "low"
}

{
  "fixedHtml": "<h2 class=\"title\">Big text</h2>",
  "explanation": "Changed the `<p>` element to an `<h2>` element. This provides a programmatically identifiable heading for the section, allowing screen readers and other assistive technologies to navigate the page by headings, thus satisfying WCAG 2.4.10. The `class=\"title\"` was retained as it likely provides visual styling and does not interfere with the semantic meaning.",
  "effort": "low"
}

{
  "fixedHtml": "<label for=\"email-input\">Email address:</label>\n<input type=\"text\" id=\"email-input\" name=\"email\">",
  "explanation": "Added a `<label>` element with a `for` attribute that matches the `id` of the `<input>` element. This creates a visible and programmatically associated label for the input field, resolving WCAG 3.3.2 by clearly indicating what information is expected.",
  "effort": "low"
}

{
  "fixedHtml": "<h1 class=\"heading1\">Introduction</h1>",
  "explanation": "The `<p>` element was replaced with an `<h1>` element. This change provides the correct semantic markup for a heading, allowing assistive technologies to identify it as such and convey the document structure to users, thereby satisfying WCAG 1.3.1.",
  "effort": "low"
}

{
  "fixedHtml": "<form>\n  <label for=\"firstname\">First name:</label>\n  <input type=\"text\" id=\"firstname\" name=\"firstname\">\n</form>",
  "explanation": "A `<label>` element was added around the visible text \"First name:\" and programmatically associated with the `<input>` using the `for` attribute on the label and a matching `id` attribute on the input. This provides an accessible name for the input, allowing assistive technologies to understand its purpose.",
  "effort": "low"
}

{
  "fixedHtml": "<img src=\"../images/animal.jpg\" alt=\"An animal\">",
  "explanation": "Added an `alt` attribute to the `<img>` element. The `alt` attribute provides a text alternative for the image, which is essential for screen readers and other assistive technologies to convey the image's purpose or content to users who cannot see it. This directly addresses WCAG 1.1.1 Non-text Content.",
  "effort": "low"
}

{
  "fixedHtml": "<p style=\"text-align: left;\">\n How much wood would a woodchuck chuck if a woodchuck could chuck wood?\n He would chuck, he would, as much as he could, and chuck as much wood\n As a woodchuck would if a woodchuck could chuck wood.\n</p>",
  "explanation": "The `text-align: justify` property was causing the paragraph text to be fully justified, leading to uneven word spacing. This can make text difficult to read for users with cognitive disabilities, violating WCAG 1.4.8. By adding an inline style `text-align: left;`, the text is now left-aligned, ensuring consistent word spacing and improved readability.",
  "effort": "low"
}

{
  "fixedHtml": "<p>A British businessman has racked up 2 million flyer miles and plans to travel on the world's first commercial tourism flights to space.</p>\n<p><a href=\"ff.html\" aria-label=\"Read More about the British businessman's space travel plans\">Read More...</a></p>",
  "explanation": "The `aria-label` attribute was added to the link. This provides a more descriptive name for assistive technologies, clarifying the link's purpose (what 'Read More...' refers to) without changing the visible link text. This resolves WCAG 2.4.4 by ensuring the link's purpose can be determined out of context.",
  "effort": "low"
}
